js='''(function(){'use strict';var cfg=JSON.parse(document.getElementById('archive-config').textContent),scene=1,question=0;var slides=[].slice.call(document.querySelectorAll('#stage>.scene'));var mode='read';var readBtn=document.getElementById('read-mode'),projectorBtn=document.getElementById('projector-mode'),jump=document.getElementById('slide-jump');function scale(){var box=document.querySelector('.projector-shell');if(!box)return;var r=box.getBoundingClientRect(),stage=document.getElementById('stage');stage.style.transform='translate(-50%,-50%) scale('+Math.min(r.width/1920,r.height/1080)+')';}function renderQuestion(){document.getElementById('jeffQuestion').textContent=cfg.questions[question];document.getElementById('questionNumber').textContent=('0'+(question+1)).slice(-2)+' / 04';document.querySelectorAll('#stage [data-jeff]').forEach(function(b){b.classList.toggle('active',Number(b.dataset.jeff)===question);b.setAttribute('aria-pressed',String(Number(b.dataset.jeff)===question));});}function show(n,scroll){scene=Math.min(cfg.count,Math.max(1,Number(n)||1));slides.forEach(function(s){var on=Number(s.dataset.scene)===scene;s.classList.toggle('active',on);s.inert=!on;s.setAttribute('aria-hidden',String(!on));});jump.value=String(scene);document.getElementById('slide-counter').textContent=('0'+scene).slice(-2)+' / '+cfg.count;document.getElementById('slide-title').textContent=cfg.titles[scene-1];document.getElementById('previous-slide').disabled=scene===1;document.getElementById('next-slide').disabled=scene===cfg.count;document.body.dataset.scene=String(scene);try{history.replaceState(null,'','#slide-'+scene)}catch(e){}if(scroll&&mode==='read')document.getElementById('read-scene-'+scene).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});renderQuestion();scale();}function setMode(next){mode=next;document.body.classList.toggle('mode-projector',mode==='projector');readBtn.setAttribute('aria-pressed',String(mode==='read'));projectorBtn.setAttribute('aria-pressed',String(mode==='projector'));scale();show(scene,mode==='read');}function move(d){if(mode==='projector'&&scene===3&&question+d>=0&&question+d<4){question+=d;renderQuestion();return;}show(scene+d,true);}readBtn.onclick=function(){setMode('read')};projectorBtn.onclick=function(){setMode('projector')};document.getElementById('previous-slide').onclick=function(){move(-1)};document.getElementById('next-slide').onclick=function(){move(1)};jump.onchange=function(){show(jump.value,true)};document.querySelectorAll('#stage [data-jeff]').forEach(function(b){b.onclick=function(){question=Number(b.dataset.jeff);renderQuestion()}});addEventListener('resize',scale);addEventListener('keydown',function(e){if(e.target.closest('input,textarea,select')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'&&mode==='projector'){e.preventDefault();setMode('read')}else if(['ArrowRight','PageDown'].includes(e.key)){e.preventDefault();move(1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();move(-1)}else if(e.key==='Home'){e.preventDefault();show(1,true)}else if(e.key==='End'){e.preventDefault();show(cfg.count,true)}});var start=Number((location.hash.match(/(?:slide-)?(\\d+)/)||[])[1])||1;show(start,start!==1);})();'''
(AS/'student.js').write_text(js)
