head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1118"><meta name="description" content="The 18-slide SSE Riga lecture archive: useful AI routines, real examples, workflow or agent, and the four-week challenge. Read on mobile or use projector view."><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; media-src data: blob:; connect-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"><title>Lecture archive · Autonomous Business Lab</title><link rel="stylesheet" href="./assets/projector.css"><link rel="stylesheet" href="./assets/student.css"></head><body class="mode-read"><a class="skip-link" href="#reading">Skip to lecture</a>'''
bar='<header class="archive-toolbar"><div class="archive-title"><strong>SSE Riga · Lecture archive</strong><span>13 October 2026 · 18 slides · Read-only · '+'v33 · student edition'+'</span></div><nav class="archive-links" aria-label="Student resources"><a href="../">Home</a><a href="../lesson/">Lesson</a><a href="../ideas/">Ideas</a><a class="download-link" href="./lecture-offline.html" download>Download HTML</a></nav><div class="mode-control" role="group" aria-label="View mode"><button id="read-mode" type="button" aria-pressed="true">Read</button><button id="projector-mode" type="button" aria-pressed="false">Projector</button></div></header>'
intro='<div class="archive-intro"><h1>Build something useful.<br>Let it run.</h1><p>The lecture as shown at SSE Riga, with recorded examples. This archive does not connect to live intake or private presenter controls. Numbers belong to their displayed dates; live classroom counters are omitted; class ideas have their own archive.</p><p><a href="./lecture-offline.html" download>Download the complete offline lecture</a> · <a href="../lesson/">Read the companion lesson</a></p></div>'
body=bar+intro+'<div class="archive-jump"><label for="slide-jump">Jump to slide</label><select id="slide-jump">'+options+'</select></div><main id="reading" class="reading">'+''.join(reading)+'</main><div class="projector-shell" aria-label="Projector view"><div id="stage"><header class="show-header"><span>Businesses that run while you sleep</span><span>SSE Riga · 13 Oct 2026</span></header>'+''.join(sections)+'</div></div><nav class="archive-navigation" aria-label="Slide navigation"><button id="previous-slide" type="button" aria-label="Previous slide">←</button><output id="slide-counter" aria-live="polite">01 / 18</output><span id="slide-title" class="nav-title"></span><button id="next-slide" type="button" aria-label="Next slide">→</button></nav><footer class="archive-footer">Workshop archive · 13 October 2026. Read mode works on phones; Projector keeps the original slide layouts. Arrow keys navigate, and Escape returns to Read mode. <a href="./version.json">Version details</a></footer><script type="application/json" id="archive-config">'+json.dumps(config).replace('<','\\u003c')+'</script><script src="./assets/student.js" defer></script><script src="./assets/three.min.js" defer></script><script src="./assets/hub-loops.js" defer></script></body></html>'
index=head+body
(OUT/'index.html').write_text(index)
offline=index.replace("script-src 'self';", "script-src 'unsafe-inline';").replace('default-src \'self\';',"default-src 'none';").replace("img-src 'self' data: blob:;","img-src data: blob:;")
for name in ['projector.css','student.css']:
 offline=offline.replace('<link rel="stylesheet" href="./assets/'+name+'">','<style>'+(AS/name).read_text()+'</style>')
for name in ['student.js','three.min.js','hub-loops.js']:
 code=(AS/name).read_text().replace('</script','<\\/script')
 offline=offline.replace('<script src="./assets/'+name+'" defer></script>','<script>'+code+'</script>')
for url,p in assets.items():
 mime=mimetypes.guess_type(p.name)[0];offline=offline.replace('src="'+url+'"','src="data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()+'"')
# Offline copy keeps destinations absolute, so file:// also links to the public hub.
offline=offline.replace('href="../','href="https://xndanius.github.io/autonomous-business-lab/').replace('href="./version.json"','href="https://xndanius.github.io/autonomous-business-lab/show/version.json"').replace('href="./lecture-offline.html" download','href="https://xndanius.github.io/autonomous-business-lab/show/lecture-offline.html" download')
(OUT/'lecture-offline.html').write_text(offline)
version['files']={'index.html':{'bytes':len(index.encode()),'sha256':hashlib.sha256(index.encode()).hexdigest()},'lecture-offline.html':{'bytes':len(offline.encode()),'sha256':hashlib.sha256(offline.encode()).hexdigest()}}
(OUT/'version.json').write_text(json.dumps(version,indent=2)+'\n')
(OUT/'README.md').write_text('# Public lecture archive\n\n18-slide, student-safe edition derived from the current presenter source. `index.html` provides a mobile reading view and the original projector layouts. `lecture-offline.html` embeds its CSS, scripts and images; links leave the offline file only when chosen. `version.json` records source hashes and the output version.\n\nThis directory deliberately contains no presenter runtime, private notes, old 8 MB fallback bundle, live API calls, credentials, automatic intake, or student submissions. Classroom counters are omitted; example numbers remain clearly dated snapshots. The original workshop wording and historical 14:00 handoff remain within the archive context.\n\nOnly the public images, original layout CSS and self-contained Three.js illustration were copied. Proof links lead to the public companion examples; slide 17 links to the workshop ideas archive.\n')
print(json.dumps({'source_sha256':source_sha,'slides':len(sections),'html_bytes':len(index.encode()),'offline_bytes':len(offline.encode()),'asset_bytes':sum(p.stat().st_size for p in AS.rglob('*')if p.is_file()),'output':str(OUT)},indent=2))
